// ===============================================================================
// DAEMIND SRE - PARSER CANÔNICO DE CHECKOUTS (TRAY, YAMPI, CARTPANDA, BAGY)
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

// 1. Identificação da plataforma de checkout
let checkoutPlat = 'Yampi';
if (body.Order && body.Order.id_tray) checkoutPlat = 'Tray';
else if (body.cart_panda_id || body.checkout_id) checkoutPlat = 'CartPanda';
else if (body.yampi_token || body.resource === 'orders') checkoutPlat = 'Yampi';
else checkoutPlat = 'Checkout Universal';

const customer = body.customer || body.Customer || body.cliente || {};
let rawPhone = (customer.phone || customer.cellphone || body.phone || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = (customer.name || customer.first_name || 'Cliente').trim();
const clienteEmail = (customer.email || '').trim().toLowerCase();
const clienteDoc = (customer.cpf || customer.document || '').toString().replace(/\D/g, '');

const numeroPedido = parseInt(body.number || body.id || body.order_id || Date.now(), 10);
const valorTotal = parseFloat(body.value_total || body.total || body.total_price || 0);
const status = (body.status?.name || body.status || body.payment_status || '').toLowerCase();

let statusOperacional = 'Pendente';
if (['paid', 'pago', 'aprovado', 'approved'].includes(status)) {
  statusOperacional = 'Pago';
} else if (['cancelled', 'cancelado', 'refunded'].includes(status)) {
  statusOperacional = 'Cancelado';
}

const dedupHash = crypto.createHash('sha256').update(`${checkoutPlat}_${numeroPedido}_${statusOperacional}_${valorTotal}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    checkout_plataforma: checkoutPlat,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    cliente_email: clienteEmail,
    cliente_whatsapp: rawPhone,
    cliente_doc: clienteDoc,
    valor_total: valorTotal,
    status_operacional: statusOperacional
  }
}];
